import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import AOS from "aos";
import "aos/dist/aos.css";

export default function ADIDroneHomePage() {
  const navigate = useNavigate();

  useEffect(() => {
    AOS.init({ duration: 800, once: true });
  }, []);

  const [counts, setCounts] = useState({ fires: 0, alerts: 0, injured: 0 });

  useEffect(() => {
    const animate = (key, target, delay = 20) => {
      let current = 0;
      const step = () => {
        if (current < target) {
          current++;
          setCounts((prev) => ({ ...prev, [key]: current }));
          setTimeout(step, delay);
        }
      };
      step();
    };
    animate("fires", 5);
    animate("alerts", 34);
    animate("injured", 12);
  }, []);

  return (
    <div className="min-h-screen bg-black text-white font-sans">
      {/* 3D Drone Background */}
      <div className="absolute top-0 left-0 right-0 w-full h-[400px] z-0 overflow-hidden opacity-40 pointer-events-none">
        <iframe
          width="100%"
          height="100%"
          src="https://fetchcfd.com/threeDViewGltf-embed-project/4927#"
          frameBorder="0"
          allow="autoplay; fullscreen; vr"
          mozallowfullscreen="true"
          webkitallowfullscreen="true"
          className="w-full h-full scale-110"
        ></iframe>
      </div>

      {/* Hero Section */}
      <section className="text-center py-20 px-6 relative z-10">
        <div>
          <h1 className="text-5xl font-bold text-cyan-400 mb-2 animate-pulse" data-aos="fade-up">
            ADI – THE THIRD EYE
          </h1>
          <p className="text-xl text-cyan-200 mb-6 uppercase tracking-wide" data-aos="fade-up">
            Vision of the Future
          </p>
          <p className="max-w-2xl mx-auto text-gray-300 mb-8" data-aos="zoom-in">
            AI-Powered Quadcopter for Crowd Control, Disaster Response, and Surveillance in India.
          </p>
          <div className="flex justify-center gap-4" data-aos="zoom-in-up">
            <button
              onClick={() => navigate("/live-demo")}
              className="bg-cyan-500 hover:bg-cyan-600 hover:shadow-xl hover:shadow-cyan-400/80 text-white px-6 py-2 rounded-xl shadow-lg transition-all duration-300 animate-glow"
            >
              ✨ LIVE DEMO
            </button>
            <button
              onClick={() => navigate("/project")}
              className="bg-gray-800 border border-cyan-500 text-cyan-200 hover:shadow-xl hover:shadow-cyan-300/70 px-6 py-2 rounded-xl transition-all duration-300"
            >
              🚀 VIEW PROJECT
            </button>
          </div>
        </div>
      </section>

      {/* ...rest of the page stays the same... */}
    </div>
  );
}
